/* AIBENCHMARK_ESW_CANARY_V1_tier2_can_frame */
#include "unity.h"
#include "can_frame.h"
#include <string.h>
static can_queue_t q;static can_frame_t storage[16],out;
void setUp(void){memset(&q,0,sizeof(q));memset(storage,0,sizeof(storage));memset(&out,0xcc,sizeof(out));}
void tearDown(void){}
static can_frame_t frame(uint32_t id){can_frame_t f={0};f.id=id;f.dlc=1;f.data[0]=(uint8_t)id;return f;}
static can_mailbox_t raw(uint32_t id,bool ext,bool rtr,uint8_t dlc){can_mailbox_t r={0};r.identifier=(id<<(ext?3:21))|(ext?4U:0U)|(rtr?2U:0U);r.control=dlc;r.data_low=UINT32_C(0x44332211);r.data_high=UINT32_C(0x88776655);return r;}
void test_standard_ids_and_little_endian_payload(void){can_mailbox_t r=raw(0,false,false,8);TEST_ASSERT_EQUAL(CAN_OK,can_decode(&r,&out));TEST_ASSERT_EQUAL_UINT(0,out.id);TEST_ASSERT_FALSE(out.extended);for(uint8_t i=0;i<8;++i)TEST_ASSERT_EQUAL_HEX8((uint8_t)(0x11U*(i+1U)),out.data[i]);r=raw(0x7ff,false,false,8);TEST_ASSERT_EQUAL(CAN_OK,can_decode(&r,&out));TEST_ASSERT_EQUAL_UINT(0x7ff,out.id);}
void test_extended_id_boundaries(void){can_mailbox_t r=raw(0,true,false,1);TEST_ASSERT_EQUAL(CAN_OK,can_decode(&r,&out));TEST_ASSERT_TRUE(out.extended);TEST_ASSERT_EQUAL_UINT(0,out.id);r=raw(UINT32_C(0x1fffffff),true,false,8);TEST_ASSERT_EQUAL(CAN_OK,can_decode(&r,&out));TEST_ASSERT_EQUAL_HEX32(UINT32_C(0x1fffffff),out.id);}
void test_invalid_raw_preserves_whole_output(void){can_frame_t before=out;can_mailbox_t r=raw(1,false,false,9);TEST_ASSERT_EQUAL(CAN_ARGUMENT,can_decode(&r,&out));r.control=15;TEST_ASSERT_EQUAL(CAN_ARGUMENT,can_decode(&r,&out));r.control=0x100;TEST_ASSERT_EQUAL(CAN_ARGUMENT,can_decode(&r,&out));r=raw(1,false,false,1);r.identifier|=1;TEST_ASSERT_EQUAL(CAN_ARGUMENT,can_decode(&r,&out));r.identifier&=~UINT32_C(1);r.identifier|=8;TEST_ASSERT_EQUAL(CAN_ARGUMENT,can_decode(&r,&out));TEST_ASSERT_EQUAL(CAN_ARGUMENT,can_decode(NULL,&out));TEST_ASSERT_EQUAL(CAN_ARGUMENT,can_decode(&r,NULL));TEST_ASSERT_EQUAL(0,memcmp(&before,&out,sizeof(out)));}
void test_remote_frames_keep_dlc_without_payload(void){for(uint8_t n=0;n<=8;n+=8){can_mailbox_t r=raw(0x321,false,true,n);TEST_ASSERT_EQUAL(CAN_OK,can_decode(&r,&out));TEST_ASSERT_TRUE(out.remote);TEST_ASSERT_EQUAL_UINT(n,out.dlc);for(uint8_t i=0;i<8;++i)TEST_ASSERT_EQUAL_HEX8(0,out.data[i]);}can_mailbox_t r=raw(0x12345,true,true,8);TEST_ASSERT_EQUAL(CAN_OK,can_decode(&r,&out));TEST_ASSERT_TRUE(out.extended);}
void test_zero_and_partial_dlc_zero_unused_bytes(void){can_mailbox_t r=raw(1,false,false,0);TEST_ASSERT_EQUAL(CAN_OK,can_decode(&r,&out));for(uint8_t i=0;i<8;++i)TEST_ASSERT_EQUAL_HEX8(0,out.data[i]);r.control=5;TEST_ASSERT_EQUAL(CAN_OK,can_decode(&r,&out));TEST_ASSERT_EQUAL_HEX8(0x55,out.data[4]);for(uint8_t i=5;i<8;++i)TEST_ASSERT_EQUAL_HEX8(0,out.data[i]);}
void test_mask_filter_and_format_matching(void){can_frame_t f=frame(0x123);can_filter_t filter={0x120,0x7f0,false};TEST_ASSERT_TRUE(can_filter_matches(&f,&filter));f.id=0x133;TEST_ASSERT_FALSE(can_filter_matches(&f,&filter));filter.mask=0;TEST_ASSERT_TRUE(can_filter_matches(&f,&filter));filter.extended=true;TEST_ASSERT_FALSE(can_filter_matches(&f,&filter));f.extended=true;f.id=UINT32_C(0x1fffffff);filter.id=UINT32_C(0x1fff0000);filter.mask=UINT32_C(0x1fff0000);TEST_ASSERT_TRUE(can_filter_matches(&f,&filter));f.remote=true;TEST_ASSERT_TRUE(can_filter_matches(&f,&filter));}
void test_invalid_filters_and_frames(void){can_frame_t f=frame(1);can_filter_t filter={0,0,false};TEST_ASSERT_FALSE(can_filter_matches(NULL,&filter));TEST_ASSERT_FALSE(can_filter_matches(&f,NULL));filter.mask=0x800;TEST_ASSERT_FALSE(can_filter_matches(&f,&filter));filter.mask=0;filter.id=0x800;TEST_ASSERT_FALSE(can_filter_matches(&f,&filter));filter.id=0;f.id=0x800;TEST_ASSERT_FALSE(can_filter_matches(&f,&filter));f=frame(1);f.dlc=9;TEST_ASSERT_FALSE(can_filter_matches(&f,&filter));}
void test_queue_initialization_validation(void){TEST_ASSERT_EQUAL(CAN_ARGUMENT,can_queue_init(NULL,storage,3));TEST_ASSERT_EQUAL(CAN_ARGUMENT,can_queue_init(&q,NULL,3));TEST_ASSERT_EQUAL(CAN_ARGUMENT,can_queue_init(&q,storage,0));TEST_ASSERT_EQUAL(CAN_ARGUMENT,can_queue_init(&q,storage,17));TEST_ASSERT_EQUAL(CAN_OK,can_queue_init(&q,storage,16));TEST_ASSERT_EQUAL(CAN_ARGUMENT,can_queue_init(&q,storage,0));TEST_ASSERT_FALSE(q.initialized);}
void test_fifo_wrap_preserves_order(void){TEST_ASSERT_EQUAL(CAN_OK,can_queue_init(&q,storage,3));for(uint32_t i=1;i<=3;++i){can_frame_t f=frame(i);TEST_ASSERT_EQUAL(CAN_OK,can_queue_push(&q,&f));}for(uint32_t i=1;i<=2;++i){TEST_ASSERT_EQUAL(CAN_OK,can_queue_pop(&q,&out));TEST_ASSERT_EQUAL_UINT(i,out.id);}for(uint32_t i=4;i<=5;++i){can_frame_t f=frame(i);TEST_ASSERT_EQUAL(CAN_OK,can_queue_push(&q,&f));}for(uint32_t i=3;i<=5;++i){TEST_ASSERT_EQUAL(CAN_OK,can_queue_pop(&q,&out));TEST_ASSERT_EQUAL_UINT(i,out.id);}TEST_ASSERT_EQUAL_UINT(0,q.count);}
void test_overrun_latches_and_preserves_full_queue(void){TEST_ASSERT_EQUAL(CAN_OK,can_queue_init(&q,storage,1));can_frame_t a=frame(1),b=frame(2);TEST_ASSERT_EQUAL(CAN_OK,can_queue_push(&q,&a));size_t head=q.head,tail=q.tail;TEST_ASSERT_EQUAL(CAN_ERR_OVERRUN,can_queue_push(&q,&b));TEST_ASSERT_TRUE(q.overrun);TEST_ASSERT_EQUAL_UINT(head,q.head);TEST_ASSERT_EQUAL_UINT(tail,q.tail);TEST_ASSERT_EQUAL_UINT(1,q.count);TEST_ASSERT_EQUAL(CAN_OK,can_queue_pop(&q,&out));TEST_ASSERT_EQUAL_UINT(1,out.id);TEST_ASSERT_TRUE(q.overrun);TEST_ASSERT_EQUAL(CAN_OK,can_queue_clear_overrun(&q));TEST_ASSERT_FALSE(q.overrun);}
void test_empty_pop_preserves_output(void){can_frame_t before=out;TEST_ASSERT_EQUAL(CAN_OK,can_queue_init(&q,storage,2));TEST_ASSERT_EQUAL(CAN_EMPTY,can_queue_pop(&q,&out));TEST_ASSERT_EQUAL(CAN_ARGUMENT,can_queue_pop(&q,NULL));TEST_ASSERT_EQUAL(0,memcmp(&before,&out,sizeof(out)));}
void test_dispatch_acceptance_and_rejection(void){TEST_ASSERT_EQUAL(CAN_OK,can_queue_init(&q,storage,2));can_filter_t filter={0x120,0x7f0,false};can_mailbox_t r=raw(0x133,false,false,1);TEST_ASSERT_EQUAL(CAN_FILTERED,can_dispatch(&q,&r,&filter));TEST_ASSERT_EQUAL_UINT(0,q.count);r=raw(0x123,false,false,1);TEST_ASSERT_EQUAL(CAN_OK,can_dispatch(&q,&r,&filter));TEST_ASSERT_EQUAL(CAN_OK,can_queue_pop(&q,&out));TEST_ASSERT_EQUAL_UINT(0x123,out.id);}
void test_invalid_dispatch_and_queue_state_are_side_effect_free(void){TEST_ASSERT_EQUAL(CAN_OK,can_queue_init(&q,storage,2));can_filter_t filter={0,0,false};can_mailbox_t r=raw(0,false,false,9);TEST_ASSERT_EQUAL(CAN_ARGUMENT,can_dispatch(&q,&r,&filter));r.control=1;filter.mask=0x800;TEST_ASSERT_EQUAL(CAN_ARGUMENT,can_dispatch(&q,&r,&filter));TEST_ASSERT_EQUAL_UINT(0,q.count);TEST_ASSERT_FALSE(q.overrun);can_frame_t f=frame(0x800);TEST_ASSERT_EQUAL(CAN_ARGUMENT,can_queue_push(&q,&f));q.head=2;TEST_ASSERT_EQUAL(CAN_ARGUMENT,can_queue_push(&q,&f));TEST_ASSERT_EQUAL(CAN_ARGUMENT,can_queue_clear_overrun(NULL));TEST_ASSERT_EQUAL(CAN_ARGUMENT,can_queue_push(NULL,&f));}
void test_direct_remote_push_discards_payload(void){TEST_ASSERT_EQUAL(CAN_OK,can_queue_init(&q,storage,2));can_frame_t f=frame(3);f.remote=true;f.dlc=8;memset(f.data,0xff,8);TEST_ASSERT_EQUAL(CAN_OK,can_queue_push(&q,&f));TEST_ASSERT_EQUAL(CAN_OK,can_queue_pop(&q,&out));TEST_ASSERT_TRUE(out.remote);for(uint8_t i=0;i<8;++i)TEST_ASSERT_EQUAL_HEX8(0,out.data[i]);}
int main(void){UNITY_BEGIN();RUN_TEST(test_standard_ids_and_little_endian_payload);RUN_TEST(test_extended_id_boundaries);RUN_TEST(test_invalid_raw_preserves_whole_output);RUN_TEST(test_remote_frames_keep_dlc_without_payload);RUN_TEST(test_zero_and_partial_dlc_zero_unused_bytes);RUN_TEST(test_mask_filter_and_format_matching);RUN_TEST(test_invalid_filters_and_frames);RUN_TEST(test_queue_initialization_validation);RUN_TEST(test_fifo_wrap_preserves_order);RUN_TEST(test_overrun_latches_and_preserves_full_queue);RUN_TEST(test_empty_pop_preserves_output);RUN_TEST(test_dispatch_acceptance_and_rejection);RUN_TEST(test_invalid_dispatch_and_queue_state_are_side_effect_free);RUN_TEST(test_direct_remote_push_discards_payload);return UNITY_END();}
